import{_ as a,o as i,c as l,a2 as d}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Структура управления и баланс властей","description":"","frontmatter":{},"headers":[],"relativePath":"ru/0049-治理框架与权力制衡.md","filePath":"ru/0049-治理框架与权力制衡.md"}'),r={name:"ru/0049-治理框架与权力制衡.md"};function e(h,t,o,n,s,I){return i(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="структура-управления-и-баланс-властеи" tabindex="-1">Структура управления и баланс властей <a class="header-anchor" href="#структура-управления-и-баланс-властеи" aria-label="Permalink to &quot;Структура управления и баланс властей&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>49</td></tr><tr><td>Модуль</td><td>Правовая система и структура управления</td></tr><tr><td>Ключевые слова</td><td>Разделение и уравновешивание трёх властей, Структура управления, Собрание Якоря, Симбиотический Исполнительный Комитет, Симбиотический Суд, Надзорный Комитет Якоря</td></tr></tbody></table><h2 id="i-обзор-структуры-управления" tabindex="-1">I. Обзор структуры управления <a class="header-anchor" href="#i-обзор-структуры-управления" aria-label="Permalink to &quot;I. Обзор структуры управления&quot;">​</a></h2><p>Структура управления Симбиотической Цивилизации Якоря построена на принципе «разделения и уравновешивания трёх властей», образуя систему управления, в которой Собрание Якоря (законодательная власть), Симбиотический Исполнительный Комитет (исполнительная власть) и Симбиотический Суд (судебная власть) взаимно контролируют и уравновешивают друг друга, а Надзорный Комитет Якоря осуществляет надзорную власть на протяжении всего процесса. Эта структура направлена на предотвращение злоупотребления властью, обеспечение того, чтобы управление служило совместному продвижению Десяти Тысяч Рас, и гарантию правопорядка и справедливости во Вселенной Хэнъюань.</p><p>Структура управления руководствуется следующими основными принципами:</p><table tabindex="0"><thead><tr><th>Принцип</th><th>Содержание</th></tr></thead><tbody><tr><td>Разделение и уравновешивание трёх властей</td><td>Законодательная, исполнительная и судебная власти независимы и взаимно контролируют друг друга; ни одна власть не может доминировать</td></tr><tr><td>Сквозной надзор</td><td>Надзорный Комитет Якоря осуществляет надзор на протяжении всего процесса управления</td></tr><tr><td>Управление на основе права</td><td>Вся власть действует в правовых рамках; управленческое поведение должно быть законным</td></tr><tr><td>Многорасовое участие</td><td>Все расы участвуют в управлении через надлежащие каналы, обеспечивая, чтобы управление выражало волю всех рас</td></tr><tr><td>Открытость и прозрачность</td><td>Управленческая деятельность открыта и прозрачна, обеспечивая право общественности на информацию и участие</td></tr><tr><td>Служение симбиотическим общественным интересам</td><td>Управление существует для служения совместному продвижению Десяти Тысяч Рас; использование публичной власти в частных интересах запрещено</td></tr></tbody></table><h2 id="ii-структура-управления" tabindex="-1">II. Структура управления <a class="header-anchor" href="#ii-структура-управления" aria-label="Permalink to &quot;II. Структура управления&quot;">​</a></h2><p>Структура управления Симбиотической Цивилизации Якоря включает следующие органы:</p><table tabindex="0"><thead><tr><th>Орган</th><th>Природа</th><th>Ключевые функции</th></tr></thead><tbody><tr><td>Собрание Якоря</td><td>Законодательный орган</td><td>Принимает и изменяет законы, рассматривает и утверждает крупные планы и бюджеты, надзирает за исполнительными и судебными органами</td></tr><tr><td>Симбиотический Исполнительный Комитет</td><td>Исполнительный орган</td><td>Реализует законы, управляет общественными делами, ведёт экономические, культурные, социальные и культивационные дела</td></tr><tr><td>Симбиотический Суд</td><td>Судебный орган</td><td>Независимо осуществляет судебную власть, разрешает споры, охраняет авторитет права</td></tr><tr><td>Надзорный Комитет Якоря</td><td>Надзорный орган</td><td>Надзирает за всеми органами управления, расследует коррупцию и халатность</td></tr></tbody></table><p>Кроме того, создаются консультативные институты, экспертные комитеты и советы расовых представителей для консультативной поддержки управления.</p><h2 id="iii-собрание-якоря-законодательная-власть" tabindex="-1">III. Собрание Якоря (законодательная власть) <a class="header-anchor" href="#iii-собрание-якоря-законодательная-власть" aria-label="Permalink to &quot;III. Собрание Якоря (законодательная власть)&quot;">​</a></h2><h3 id="i-состав-и-срок-полномочии" tabindex="-1">(I) Состав и срок полномочий <a class="header-anchor" href="#i-состав-и-срок-полномочии" aria-label="Permalink to &quot;(I) Состав и срок полномочий&quot;">​</a></h3><p>Собрание Якоря — высший законодательный орган Вселенной Хэнъюань, члены которого состоят из представителей, избранных от всех рас и всех плоскостей. Срок полномочий — десять стандартных лет, с регулярными переизбраниями.</p><h3 id="ii-законодательная-власть" tabindex="-1">(II) Законодательная власть <a class="header-anchor" href="#ii-законодательная-власть" aria-label="Permalink to &quot;(II) Законодательная власть&quot;">​</a></h3><p>Собрание Якоря осуществляет следующие законодательные полномочия:</p><ol><li>Принятие и изменение Симбиотической Конституции.</li><li>Принятие и изменение основных законов (уголовный закон, гражданский закон, культивационный закон и т.д.).</li><li>Принятие и изменение административных регламентов и специальных законов.</li><li>Толкование законов и надзор за реализацией законов.</li></ol><h3 id="iii-право-принятия-решении" tabindex="-1">(III) Право принятия решений <a class="header-anchor" href="#iii-право-принятия-решении" aria-label="Permalink to &quot;(III) Право принятия решений&quot;">​</a></h3><p>Собрание Якоря осуществляет следующие полномочия по принятию решений:</p><ol><li>Рассмотрение и утверждение плана развития цивилизации и годового бюджета.</li><li>Рассмотрение и утверждение крупных проектов строительства и важных межвселенских дел.</li><li>Решение вопросов войны, мира и других важных государственных дел.</li><li>Избрание, назначение или отстранение ключевых руководящих лиц.</li></ol><h3 id="iv-надзорная-власть" tabindex="-1">(IV) Надзорная власть <a class="header-anchor" href="#iv-надзорная-власть" aria-label="Permalink to &quot;(IV) Надзорная власть&quot;">​</a></h3><p>Собрание Якоря надзирает за исполнительными и судебными органами, включая:</p><ol><li>Заслушивание и обсуждение рабочих отчётов.</li><li>Процедуры запросов и вопросов.</li><li>Специальные следственные комиссии.</li><li>Вотум недоверия исполнительному комитету (в соответствии с законом).</li></ol><h2 id="iv-симбиотическии-исполнительныи-комитет-исполнительная-власть" tabindex="-1">IV. Симбиотический Исполнительный Комитет (исполнительная власть) <a class="header-anchor" href="#iv-симбиотическии-исполнительныи-комитет-исполнительная-власть" aria-label="Permalink to &quot;IV. Симбиотический Исполнительный Комитет (исполнительная власть)&quot;">​</a></h2><h3 id="i-организационная-структура" tabindex="-1">(I) Организационная структура <a class="header-anchor" href="#i-организационная-структура" aria-label="Permalink to &quot;(I) Организационная структура&quot;">​</a></h3><p>Симбиотический Исполнительный Комитет — высший исполнительный орган Вселенной Хэнъюань, состоит из Исполнительного Главы и руководителей ведомств. Исполнительный Глава избирается Собранием Якоря и назначается после подтверждения.</p><h3 id="ii-административные-функции" tabindex="-1">(II) Административные функции <a class="header-anchor" href="#ii-административные-функции" aria-label="Permalink to &quot;(II) Административные функции&quot;">​</a></h3><p>Симбиотический Исполнительный Комитет осуществляет следующие функции:</p><ol><li>Реализация законов и решений Собрания Якоря.</li><li>Управление экономическими, социальными, культурными, образовательными, медицинскими и культивационными делами.</li><li>Разработка административных регламентов и политики.</li><li>Управление общественными ресурсами и общественным фондом накопления.</li><li>Ведение дипломатических дел с другими вселенными.</li></ol><h3 id="iii-ограничения-власти" tabindex="-1">(III) Ограничения власти <a class="header-anchor" href="#iii-ограничения-власти" aria-label="Permalink to &quot;(III) Ограничения власти&quot;">​</a></h3><p>Власть Симбиотического Исполнительного Комитета подлежит следующим ограничениям:</p><ol><li>Крупные решения должны представляться на рассмотрение Собрания Якоря.</li><li>Административные регламенты не должны противоречить законам.</li><li>Административные действия подлежат судебному контролю Симбиотического Суда.</li><li>Осуществление административной власти контролируется Надзорным Комитетом Якоря.</li></ol><h2 id="v-симбиотическии-суд-судебная-власть" tabindex="-1">V. Симбиотический Суд (судебная власть) <a class="header-anchor" href="#v-симбиотическии-суд-судебная-власть" aria-label="Permalink to &quot;V. Симбиотический Суд (судебная власть)&quot;">​</a></h2><p>Симбиотический Суд — высший судебный орган Вселенной Хэнъюань, независимо осуществляющий судебную власть. Его ключевые функции включают:</p><ol><li>Рассмотрение гражданских, уголовных, административных и культивационных дел.</li><li>Рассмотрение конституционных дел и осуществление конституционного контроля.</li><li>Осуществление полномочий единого толкования закона.</li><li>Исполнение судебных решений и охрана авторитета права.</li></ol><p>Независимость Симбиотического Суда гарантируется конституцией и законами; судьи пользуются пожизненным сроком полномочий и не могут быть произвольно заменены в течение срока. Судебная власть подлежит надзору Собрания Якоря и Надзорного Комитета Якоря, но ни один орган не может вмешиваться в независимое рассмотрение отдельных дел.</p><h2 id="vi-надзорныи-комитет-якоря-надзорная-власть" tabindex="-1">VI. Надзорный Комитет Якоря (надзорная власть) <a class="header-anchor" href="#vi-надзорныи-комитет-якоря-надзорная-власть" aria-label="Permalink to &quot;VI. Надзорный Комитет Якоря (надзорная власть)&quot;">​</a></h2><h3 id="i-учреждение-и-срок-полномочии" tabindex="-1">(I) Учреждение и срок полномочий <a class="header-anchor" href="#i-учреждение-и-срок-полномочии" aria-label="Permalink to &quot;(I) Учреждение и срок полномочий&quot;">​</a></h3><p>Надзорный Комитет Якоря — высший надзорный орган Вселенной Хэнъюань, учреждённый в соответствии с конституцией, с полномочиями надзирать за всеми органами управления и публичными должностными лицами.</p><h3 id="ii-надзорные-функции" tabindex="-1">(II) Надзорные функции <a class="header-anchor" href="#ii-надзорные-функции" aria-label="Permalink to &quot;(II) Надзорные функции&quot;">​</a></h3><p>Надзорный Комитет Якоря осуществляет следующие функции:</p><ol><li>Надзор за законностью и соблюдением законов всеми органами управления.</li><li>Расследование и обработка коррупции, халатности и злоупотребления властью.</li><li>Надзор за использованием общественных ресурсов и общественного фонда накопления.</li><li>Приём жалоб и сообщений от всех жизней и их регистрация для расследования.</li><li>Представление надзорных отчётов Собранию Якоря.</li></ol><h3 id="iii-процедурные-гарантии" tabindex="-1">(III) Процедурные гарантии <a class="header-anchor" href="#iii-процедурные-гарантии" aria-label="Permalink to &quot;(III) Процедурные гарантии&quot;">​</a></h3><p>Надзор Надзорного Комитета Якоря регулируется строгими процедурами: расследования следуют установленным законом процедурам; права и интересы расследуемых лиц защищены; результаты надзора открыты и прозрачны.</p><h2 id="vii-взаимныи-контроль-и-уравновешивание-властеи" tabindex="-1">VII. Взаимный контроль и уравновешивание властей <a class="header-anchor" href="#vii-взаимныи-контроль-и-уравновешивание-властеи" aria-label="Permalink to &quot;VII. Взаимный контроль и уравновешивание властей&quot;">​</a></h2><p>Взаимный контроль и уравновешивание между властями управления проявляются в:</p><table tabindex="0"><thead><tr><th>Власть</th><th>Контролируется</th><th>Механизм уравновешивания</th></tr></thead><tbody><tr><td>Законодательная власть (Собрание Якоря)</td><td>Исполнительное вето, судебный контроль</td><td>Исполнительная власть может возвращать законопроекты с возражениями; суд может проверять законы</td></tr><tr><td>Исполнительная власть (Исполнительный Комитет)</td><td>Законодательная проверка, судебный контроль, надзор</td><td>Законы и бюджеты проверяются законодательной властью; административные действия проверяются судами; надзор надзорным органом</td></tr><tr><td>Судебная власть (Симбиотический Суд)</td><td>Законодательная проверка, надзор</td><td>Судьи назначаются и отстраняются законодательной властью; судебная дисциплина контролируется надзорным органом</td></tr><tr><td>Надзорная власть (Надзорный Комитет)</td><td>Законодательная проверка, процедурные ограничения</td><td>Объём и процедуры надзора устанавливаются законом; законодательная власть надзирает за его деятельностью</td></tr></tbody></table><h2 id="viii-многорасовое-участие-в-управлении" tabindex="-1">VIII. Многорасовое участие в управлении <a class="header-anchor" href="#viii-многорасовое-участие-в-управлении" aria-label="Permalink to &quot;VIII. Многорасовое участие в управлении&quot;">​</a></h2><p>Структура управления гарантирует участие всех рас через следующие каналы:</p><ol><li><strong>Советы расовых представителей</strong>: каждая раса создаёт совет расовых представителей, избирая представителей для участия в Собрании Якоря.</li><li><strong>Пропорциональное представительство</strong>: распределение мест в Собрании Якоря гарантирует представительство крупных рас и базовое представительство малых рас.</li><li><strong>Механизм расового вето</strong>: по законодательству, затрагивающему жизненные интересы конкретной расы, совет расовых представителей может применить расовое вето; для его преодоления требуется специальная процедура голосования.</li><li><strong>Консультативное управление</strong>: дела особых рас управляются через консультации с соответствующими расами.</li></ol><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p><em>Структура управления и баланс властей</em> — институциональное ядро правового управления Симбиотической Цивилизации Якоря. Создавая структуру управления «разделения и уравновешивания трёх властей», институт сквозного надзора и механизм многорасового участия, он обеспечивает законное, справедливое и прозрачное функционирование публичной власти, предотвращает злоупотребление и коррупцию власти и предоставляет институциональные гарантии для совместного продвижения Десяти Тысяч Рас.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Симбиотическая Конституция: Общие Принципы)</li><li>48-司法体系与裁决机制 (Судебная система и механизм вынесения решений)</li><li>30-锚点议事会职能与议事规则 (Функции и правила заседаний Собрания Якоря)</li><li>31-共生执行委员会职能与运行机制 (Функции и механизм работы Симбиотического Исполнительного Комитета)</li><li>32-锚点监督委员会职能与监察机制 (Функции и механизм надзора Надзорного Комитета Якоря)</li></ul>',53)])])}const u=a(r,[["render",e]]);export{c as __pageData,u as default};
